        return (
          JSON.parse(readFileSync(stateFile, "utf8"))[OPENCODE_GO_PROVIDER] ===
          OPENCODE_GO_ADAPTER_ID
        );
      } catch {
        return false;
      }
    });

    for (const dispose of [...disposers].reverse()) {
      try {
        dispose();
      } catch {}
    }
  });

