  beforeAll(async () => {
    const dir = mkdtempSync(join(tmpdir(), "dou-stats-"));
    const goodFile = join(dir, "good.mjs");
    writeFileSync(goodFile, adapterMjs("stats-adp"), "utf8");
    const { ctx, routes } = makeCtx();
    await apply(ctx, {
