    const hNoAdp = makeRes();
    await historyR?.handler(fakeReq({ url: `${ROUTES.history}?provider=ghost` }), hNoAdp);
    noAdpBody = JSON.parse(hNoAdp._body());

    // days 参数：合法窗口取 min(days, maxAgeDays)
